{number:1,type:"mcq",marks:2,topic:"Matter",subtopic:"States of matter",skill:"Application",difficulty:"standard",question:"A sealed bottle contains ice cubes. The ice cubes melt completely. Which statement is correct?",options:["The total mass decreases.","The total mass increases.","The total mass remains the same.","The water has no particles."],answer:"C",explanation:"Melting changes the state of water but does not change the amount of matter."},
{number:2,type:"mcq",marks:2,topic:"Interactions",subtopic:"Forces",skill:"Application",difficulty:"standard",question:"A toy car is pushed across a rough floor. Why does it eventually stop?",options:["Friction acts against its motion.","Gravity stops the car.","The car loses all its mass.","The floor pushes the car forward."],answer:"A",explanation:"Friction opposes motion between surfaces."},
{number:3,type:"mcq",marks:2,topic:"Energy",subtopic:"Heat transfer",skill:"Application",difficulty:"standard",question:"A metal spoon is left in a cup of hot soup. After a while, the handle becomes warm. What has mainly happened?",options:["Light energy travelled through the spoon.","Heat was transferred through the spoon.","The spoon produced heat by itself.","The soup changed into metal."],answer:"B",explanation:"Thermal energy is transferred through the metal spoon."},
{number:4,type:"mcq",marks:2,topic:"Cycles",subtopic:"Water cycle",skill:"Knowledge",difficulty:"standard",question:"Which process changes liquid water into water vapour?",options:["Condensation","Freezing","Evaporation","Melting"],answer:"C",explanation:"Evaporation is the change from liquid water to water vapour."},
{number:5,type:"mcq",marks:2,topic:"Living Things",subtopic:"Plants",skill:"Application",difficulty:"standard",question:"A plant is placed in darkness for several days. Which process is directly affected most?",options:["Photosynthesis","Digestion","Respiration only","Excretion"],answer:"A",explanation:"Plants require light for photosynthesis."},
{number:6,type:"mcq",marks:2,topic:"Living Things",subtopic:"Human systems",skill:"Application",difficulty:"standard",question:"Which organ system carries digested nutrients from the small intestine to the rest of the body?",options:["Respiratory system","Circulatory system","Skeletal system","Nervous system"],answer:"B",explanation:"Blood in the circulatory system transports absorbed nutrients."},
{number:7,type:"mcq",marks:2,topic:"Interactions",subtopic:"Magnets",skill:"Inference",difficulty:"standard",question:"A student brings one end of a magnet near both ends of another magnet. It repels one end and attracts the other. What can be concluded?",options:["The second object is definitely made of wood.","The second object is a magnet.","The second object contains water.","The first magnet has no poles."],answer:"B",explanation:"Repulsion is evidence that both objects have magnetic poles."},
{number:8,type:"mcq",marks:2,topic:"Cycles",subtopic:"Reproduction",skill:"Knowledge",difficulty:"standard",question:"Which is the main function of seeds in flowering plants?",options:["To absorb sunlight","To develop into new plants","To make soil","To produce sound"],answer:"B",explanation:"Seeds contain the embryo and can develop into new plants under suitable conditions."},
{number:9,type:"mcq",marks:2,topic:"Matter",subtopic:"Changes of state",skill:"Application",difficulty:"standard",question:"Water droplets form on the outside of a cold glass. Where did the water come from?",options:["The glass changed into water.","Water vapour in the surrounding air condensed.","The cold glass produced water.","The table released water vapour."],answer:"B",explanation:"Water vapour in the air cools and condenses on the cold surface."},
{number:10,type:"mcq",marks:2,topic:"Energy",subtopic:"Light",skill:"Application",difficulty:"standard",question:"A student stands behind an opaque object while a lamp is switched on. Why can the student not see the lamp?",options:["Opaque objects block light.","Opaque objects create darkness everywhere.","Light travels only downwards.","The lamp stops producing light."],answer:"A",explanation:"Opaque materials do not allow light to pass through them."},
{number:11,type:"mcq",marks:2,topic:"Living Things",subtopic:"Respiration",skill:"Application",difficulty:"standard",question:"During vigorous exercise, a person's breathing rate increases mainly because the body needs more",options:["water for digestion.","oxygen for respiration.","sunlight for photosynthesis.","bone cells for movement."],answer:"B",explanation:"Muscles require more energy during exercise, so the body increases oxygen supply for respiration."},
{number:12,type:"mcq",marks:2,topic:"Interactions",subtopic:"Forces",skill:"Analysis",difficulty:"standard",question:"Two students push a box in opposite directions with equal force. What is most likely to happen?",options:["The box accelerates strongly to the left.","The box accelerates strongly to the right.","The forces are balanced.","The box disappears."],answer:"C",explanation:"Equal opposite forces are balanced, so there is no change in motion due to those forces."},
{number:13,type:"mcq",marks:2,topic:"Matter",subtopic:"Solubility",skill:"Application",difficulty:"standard",question:"Which action would usually make sugar dissolve faster in water?",options:["Stirring the mixture","Removing all the water","Using a larger sugar cube","Leaving the mixture untouched"],answer:"A",explanation:"Stirring increases contact between sugar and water."},
{number:14,type:"mcq",marks:2,topic:"Energy",subtopic:"Electrical systems",skill:"Application",difficulty:"standard",question:"A bulb in a simple circuit does not light up. Which change could complete the circuit?",options:["Remove the battery.","Open the switch.","Connect the loose wire properly.","Remove the bulb."],answer:"C",explanation:"A complete conducting path is needed for current to flow."},
{number:15,type:"mcq",marks:2,topic:"Cycles",subtopic:"Food chains",skill:"Analysis",difficulty:"standard",question:"In a food chain grass → grasshopper → frog, which organism is the producer?",options:["Grass","Grasshopper","Frog","All three"],answer:"A",explanation:"Plants are producers because they make their own food."},
{number:16,type:"mcq",marks:2,topic:"Living Things",subtopic:"Adaptation",skill:"Application",difficulty:"standard",question:"A polar bear has thick fur and a layer of fat. How do these features help it?",options:["They help it absorb more sunlight.","They reduce heat loss.","They make it produce food.","They increase water loss."],answer:"B",explanation:"Thick fur and fat help reduce heat loss in cold surroundings."},
{number:17,type:"mcq",marks:2,topic:"Interactions",subtopic:"Air resistance",skill:"Application",difficulty:"standard",question:"A parachute opens as a person falls. Why does the person then fall more slowly?",options:["Air resistance increases.","Gravity disappears.","The person's mass becomes zero.","The parachute pulls the person upward with no force."],answer:"A",explanation:"The larger parachute surface area increases air resistance."},
{number:18,type:"mcq",marks:2,topic:"Energy",subtopic:"Sound",skill:"Application",difficulty:"standard",question:"Which situation best shows that sound needs a medium to travel?",options:["A bell can be heard through air.","A person sees a flash of light.","A shadow forms behind an object.","A plant grows towards light."],answer:"A",explanation:"Sound vibrations travel through a medium such as air."},
{number:19,type:"mcq",marks:2,topic:"Living Things",subtopic:"Reproduction",skill:"Application",difficulty:"standard",question:"Why do flowering plants produce fruits after fertilisation?",options:["Fruits help protect and disperse seeds.","Fruits make the plant breathe.","Fruits replace the roots.","Fruits absorb all sunlight."],answer:"A",explanation:"Fruits develop around seeds and can help protect or disperse them."},
{number:20,type:"mcq",marks:2,topic:"Matter",subtopic:"Materials",skill:"Evaluation",difficulty:"standard",question:"A student needs a material for the handle of a cooking pan. Which property is most important?",options:["Good heat conductor","Poor heat conductor","Very high density only","Ability to dissolve in water"],answer:"B",explanation:"A pan handle should reduce heat transfer to the user's hand."},
{number:21,type:"mcq",marks:2,topic:"Cycles",subtopic:"Water cycle",skill:"Prediction",difficulty:"standard",question:"A wet cloth is placed under a fan instead of in still air. What is most likely to happen?",options:["It dries more quickly.","It cannot dry.","The water freezes immediately.","The cloth gains water."],answer:"A",explanation:"Moving air increases evaporation from the cloth."},
{number:22,type:"mcq",marks:2,topic:"Interactions",subtopic:"Forces",skill:"Analysis",difficulty:"higher",question:"A student pushes two identical boxes with the same force. Box X moves more easily because its surface is smoother. Which force is smaller for Box X?",options:["Friction","Gravity","Weight","Mass"],answer:"A",explanation:"A smoother contact surface generally produces less friction."},
{number:23,type:"mcq",marks:2,topic:"Energy",subtopic:"Energy transfer",skill:"Application",difficulty:"higher",question:"A solar-powered toy moves when placed under bright sunlight. Which energy change best describes this?",options:["Light energy is converted into useful movement energy.","Sound energy becomes light energy.","Heat energy becomes matter.","Chemical energy becomes sunlight."],answer:"A",explanation:"The solar cell converts light energy into electrical energy, which powers the motor."},
{number:24,type:"mcq",marks:2,topic:"Living Things",subtopic:"Human systems",skill:"Analysis",difficulty:"higher",question:"If the small intestine cannot absorb nutrients properly, which process will be affected most directly?",options:["Transport of nutrients to body cells","Movement of air into the lungs","Removal of urine from the body","Detection of sound"],answer:"A",explanation:"The small intestine absorbs digested nutrients for transport in the blood."},
{number:25,type:"mcq",marks:2,topic:"Matter",subtopic:"Separation",skill:"Application",difficulty:"higher",question:"A mixture contains sand and water. Which method is most suitable for separating them?",options:["Filtration","Melting","Magnetism","Condensation"],answer:"A",explanation:"Filtration separates an insoluble solid from a liquid."},
{number:26,type:"mcq",marks:2,topic:"Cycles",subtopic:"Plant reproduction",skill:"Analysis",difficulty:"higher",question:"A flower has its stamens removed before pollen can reach the stigma. What is the most likely result?",options:["Fertilisation may not occur.","The roots stop absorbing water immediately.","The leaves become transparent.","The stem becomes magnetic."],answer:"A",explanation:"Pollen is needed to deliver the male reproductive cell for fertilisation."},
{number:27,type:"mcq",marks:2,topic:"Interactions",subtopic:"Investigations",skill:"Evaluation",difficulty:"higher",question:"A student tests which material is the best thermal insulator. Which variable should be kept the same for a fair test?",options:["The material being tested","The thickness of each material","The result","The conclusion"],answer:"B",explanation:"Keeping thickness the same helps ensure the comparison is fair."},
{number:28,type:"mcq",marks:2,topic:"Energy",subtopic:"Heat transfer",skill:"Prediction",difficulty:"higher",question:"Two identical cups contain equal amounts of hot water. One is wrapped in a thick insulating material. Which cup should remain hot for longer?",options:["The wrapped cup","The unwrapped cup","Both will cool at exactly the same rate","Neither cup can lose heat"],answer:"A",explanation:"Insulation reduces the rate of heat transfer to the surroundings."},
{number:29,type:"mcq",marks:2,topic:"Living Things",subtopic:"Ecosystems",skill:"Analysis",difficulty:"higher",question:"If the number of frogs in a pond decreases greatly, which population may increase first if frogs eat many insects?",options:["Insects","Plants that insects never eat","Rocks","Sunlight"],answer:"A",explanation:"Fewer predators can allow their prey population to increase."},
{number:30,type:"mcq",marks:2,topic:"Scientific Inquiry",subtopic:"Variables",skill:"Evaluation",difficulty:"higher",question:"A student investigates whether the amount of sunlight affects plant growth. Which should be measured as the dependent variable?",options:["Amount of sunlight given","Type of plant","Height of the plant","Size of the pot"],answer:"C",explanation:"Plant height is the outcome being measured."}
